"""Writes the Linux shell's icon (an HVIF vector_icon) into
src/apps/linuxshell/LinuxShellIcon.rdef:

    3rdparty/ce/tools/make_linux_shell_icon.py > \\
        src/apps/linuxshell/LinuxShellIcon.rdef
    3rdparty/ce/tools/make_linux_shell_icon.py --preview icon.png

The picture: a terminal window in Haiku's three-quarter style, a dark
screen under a Renga-green title bar, with a green prompt chevron, a gold
cursor bar and an orange "L" for Linux at the right. No mascot or
trademark.
"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import hvif

GREEN = ((126, 190, 74, 255), (78, 140, 46, 255))
ORANGE = ((240, 128, 40, 255), (196, 84, 22, 255))
GOLD = ((246, 196, 64, 255), (206, 150, 30, 255))
SCREEN = ((52, 56, 48, 255), (14, 15, 12, 255))
FRAME = ((210, 206, 194, 255), (140, 136, 124, 255))
OUTLINE = (30, 32, 26, 255)


def skew(points):
	# a slight three-quarter view, as Haiku's icons lean
	return [(x + (40 - y) * 0.12, y) for x, y in points]


def rounded_rect(x0, y0, x1, y1, r):
	points = []
	points += hvif.arc_points(x1 - r, y0 + r, r, -90, 0, 4)
	points += hvif.arc_points(x1 - r, y1 - r, r, 0, 90, 4)
	points += hvif.arc_points(x0 + r, y1 - r, r, 90, 180, 4)
	points += hvif.arc_points(x0 + r, y0 + r, r, 180, 270, 4)
	return points


def build():
	icon = hvif.Icon()
	# the window: frame, title bar, screen
	icon.polygon(skew(rounded_rect(6, 10, 58, 54, 4)), hvif.gradient(
		(6, 10), (58, 54), [(0, FRAME[0]), (255, FRAME[1])]),
		outline=(OUTLINE, 3))
	icon.polygon(skew([(9, 13), (55, 13), (55, 19), (9, 19)]), hvif.gradient(
		(9, 13), (55, 19), [(0, GREEN[0]), (255, GREEN[1])]))
	icon.polygon(skew([(9, 21), (55, 21), (55, 51), (9, 51)]), hvif.gradient(
		(9, 21), (55, 51), [(0, SCREEN[0]), (255, SCREEN[1])]))
	# prompt chevron
	icon.polygon(skew([(14, 28), (17, 28), (25, 34), (17, 40), (14, 40),
		(22, 34)]), hvif.gradient((14, 28), (25, 40),
		[(0, GREEN[0]), (255, GREEN[1])]))
	# cursor bar
	icon.polygon(skew([(27, 38), (36, 38), (36, 41), (27, 41)]),
		hvif.gradient((27, 38), (36, 41), [(0, GOLD[0]), (255, GOLD[1])]))
	# the "L"
	icon.polygon(skew([(42, 26), (46, 26), (46, 42), (52, 42), (52, 46),
		(42, 46)]), hvif.gradient((42, 26), (52, 46),
		[(0, ORANGE[0]), (255, ORANGE[1])]))
	return icon


def rdef():
	data = build().flat()
	hexdata = data.hex().upper()
	lines = ["/*", " * Copyright 2026, Renga contributors.",
		" * Distributed under the terms of the MIT License.", " *",
		" * The Linux shell's icon. Generated by",
		" * 3rdparty/ce/tools/make_linux_shell_icon.py; see there.",
		" */", "", "resource vector_icon {"]
	for i in range(0, len(hexdata), 64):
		lines.append("\t$\"%s\"" % hexdata[i:i + 64])
	lines.append("};")
	return "\n".join(lines) + "\n"


if __name__ == "__main__":
	if len(sys.argv) == 3 and sys.argv[1] == "--preview":
		from PIL import Image
		icon = build()
		sheet = Image.new("RGBA", (16 + 32 + 64 + 128 + 40, 140),
			(216, 216, 216, 255))
		x = 8
		for size in (16, 32, 64, 128):
			sheet.paste(icon.preview(size, (216, 216, 216, 255)), (x, 4))
			x += size + 8
		sheet.save(sys.argv[2])
	else:
		print(rdef(), end="")
